/* =========================================================
   心声美化➠想修改心声美化就改这里
   ========================================================= */

/* 1. 强制给顶栏定锚，并且彻底解除裁切 */
.chat-thread-top {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  overflow: visible !important;
  z-index: 50 !important;
}

.chat-thread-pill {
  overflow: visible !important;
  position: relative !important; /* 给流苏提供定位基准 */
}

/* 2. 强行剥离原生按钮 */
.chat-thread-head-xinsheng {
  position: absolute !important;
  top: calc(100% - 5px) !important; /* 悬挂在顶栏下方 */
  right: 20px !important; /* 靠右悬挂，可自行改 left */

  /* 暴力重设宽高，防止被原生限制压扁 */
  width: 45px !important;
  height: 85px !important;
  min-width: 45px !important;
  min-height: 90px !important;
  max-width: none !important;

  /* 强行覆盖背景图 */
  background: transparent url("https://pic.imgdd.cc/i/034ue7o1G8h3QdVccs50I5.png") top center / contain no-repeat !important;

  /* 清除所有的边距、边框、原生颜色 */
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;

  /* 强行拉高层级，保证在最上面 */
  z-index: 9999 !important;
  pointer-events: auto !important;
  cursor: pointer !important;

  /* 动效：钟摆摇晃 + 柔光 */
  transform-origin: top center !important;
  animation: pink-swing 2.2s cubic-bezier(0.45, 0.05, 0.55, 0.95) infinite alternate !important;
  filter: drop-shadow(0 4px 8px rgba(239, 181, 202, 0.6)) brightness(1.05) !important;
}

/* 3. 彻底摧毁内部原有的图标和排版文字 */
.chat-thread-head-xinsheng * {
  display: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
  font-size: 0 !important;
  width: 0 !important;
  height: 0 !important;
}

/* 4. 点击反馈 */
.chat-thread-head-xinsheng:active {
  animation-play-state: paused !important;
  transform: scale(1.1) rotate(0) !important;
  filter: drop-shadow(0 0 15px rgba(239, 181, 202, 1)) brightness(1.2) !important;
}

@keyframes pink-swing {
  0% { transform: rotate(-10deg); }
  100% { transform: rotate(10deg); }
}
